{
  "name": "Newport光谱光源设备",
  "name_en": "Newport spectral light-source instrument",
  "manufacturer": "Newport Corporation",
  "description": "一类Newport光学光源/光谱设备，可进行开关控制并获取光谱数据，常用于光学表征、照明校准以及光伏实验中的光谱测量。",
  "description_en": "A Newport optical source/spectral instrument that can be switched on and off and acquire spectrum data, commonly used for optical characterization, illumination calibration, and spectral measurements in photovoltaic experiments.",
  "actions": [
    {
      "action_name": "auto-on",
      "description": "打开设备输出",
      "description_en": "Turn on the device output."
    },
    {
      "action_name": "auto-off",
      "description": "关闭设备输出",
      "description_en": "Turn off the device output."
    },
    {
      "action_name": "auto-get_spectrum",
      "description": "获取当前光谱数据",
      "description_en": "Acquire the current spectrum."
    }
  ],
  "tag_hints": [
    "optical spectroscopy",
    "light source control",
    "spectrum acquisition",
    "photovoltaic testing",
    "illumination calibration"
  ]
}

